#include <stdio.h>
#include <string.h>

#define MAX_SUBS 10

typedef struct { int id; void (*on_msg)(int, char*); } Subscriber;

typedef struct { char name[32]; Subscriber *subs[MAX_SUBS]; int count; } Topic;

void topic_init(Topic *t, char *name) { strcpy(t->name, name); t->count = 0; }
void topic_subscribe(Topic *t, Subscriber *s) {
    if (t->count < MAX_SUBS) t->subs[t->count++] = s;
}
void topic_publish(Topic *t, char *msg) {
    for (int i = 0; i < t->count; i++)
        t->subs[i]->on_msg(t->subs[i]->id, msg);
}

void news_callback(int id, char *msg) { printf("Sub %d got: %s\n", id, msg); }

int main() {
    Topic news;
    topic_init(&news, "news");
    Subscriber s1 = {1, news_callback};
    Subscriber s2 = {2, news_callback};
    topic_subscribe(&news, &s1);
    topic_subscribe(&news, &s2);
    topic_publish(&news, "Hello everyone!");
    return 0;
}
